declare_lint_rule! {
    /// Disallow a stray `$` at the end of a JSX text node placed right before a JSX expression.
    ///
    /// When migrating from template literals to JSX, it is easy to leave behind
    /// the `$` of a `${expression}` interpolation. In JSX, such a `$` is rendered
    /// verbatim as text, which is almost never intended.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```jsx,expect_diagnostic
    /// <div>Total: ${price}</div>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```jsx
    /// <div>Total: {price}</div>
    /// ```
    ///
    /// A lone `$` before a single expression is treated as intentional, e.g. to
    /// display a currency symbol:
    ///
    /// ```jsx
    /// <div>${price}</div>
    /// ```
    pub NoJsxLeakedDollar {
        version: "next",
        name: "noJsxLeakedDollar",
        language: "jsx",
        recommended: false,
        severity: Severity::Information,
        fix_kind: FixKind::Unsafe,
    }
}

impl Rule for NoJsxLeakedDollar {
    type Query = Ast<JsxText>;
    /// Range of the offending trailing `$` character.
    type State = TextRange;
    type Signals = Option<Self::State>;
    type Options = NoJsxLeakedDollarOptions;

    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let text = token.text_trimmed();

        // The text node must end with a `$`.
        if !text.ends_with('$') {
            return None;
        }

        // The immediately following sibling must be a JSX expression child.
        let next = node.syntax().next_sibling()?;
        if next.kind() != JsSyntaxKind::JSX_EXPRESSION_CHILD {
            return None;
        }

        // A lone `$` before a single expression is treated as intentional
        // (e.g. displaying a currency value), but only when the parent element
        // has exactly the two children: this text node and the expression.
        if text == "$" {
            let list = node.parent::<JsxChildList>()?;
            if list.len() == 2 {
                return None;
            }
        }

        let range = token.text_trimmed_range();
        let dollar_start = range.end() - TextSize::from(1);
        Some(TextRange::new(dollar_start, range.end()))
    }

    fn diagnostic(_: &RuleContext<Self>, range: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                range,
                markup! {
                    "Possible unintentional '$' before a JSX expression."
                },
            )
            .note(markup! {
                "This '$' will be rendered as text. Remove the '$' from the text node or add a suppression if it is intentional."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, _: &Self::State) -> Option<JsRuleAction> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let text = token.text();

        // Remove only the trailing `$`, leaving the rest of the text intact.
        let new_text = &text[..text.len() - 1];
        let new_jsx_text = AnyJsxChild::JsxText(make::jsx_text(JsSyntaxToken::new_detached(
            JsSyntaxKind::JSX_TEXT,
            new_text,
            [],
            [],
        )));

        let mut mutation = ctx.root().begin();
        mutation.replace_node(AnyJsxChild::from(node.clone()), new_jsx_text);

        Some(JsRuleAction::new(
            ctx.metadata().action_category(ctx.category(), ctx.group()),
            ctx.metadata().applicability(),
            markup! { "Remove dollar sign." }.to_owned(),
            mutation,
        ))
    }
